<template><section class="page"><header><p class="eyebrow">Resident dashboard</p><h1>Request a cleanup</h1><p>Tell us about an area, street, or place that needs attention. Our team will review your request and keep you updated.</p></header><p v-if="message" :class="['message',error?'error':'success']">{{message}}</p><div class="layout"><form class="card" @submit.prevent="submit"><h2>New request</h2><label>Place or area name<input v-model.trim="form.location_name" required placeholder="e.g. Park near Rosewood Street"/></label><label>Street address / landmark<input v-model.trim="form.address" required placeholder="Street number, intersection or nearby landmark"/></label><label>Suburb<input v-model.trim="form.suburb" required placeholder="e.g. Manenberg"/></label><label>What needs to be cleaned?<textarea v-model.trim="form.description" required rows="4" placeholder="Describe the waste, illegal dumping or area of concern."></textarea></label><label>Preferred date <small>(optional)</small><input v-model="form.preferred_date" type="date" :min="today"/></label><button :disabled="saving">{{saving?'Sending…':'Send cleanup request'}}</button></form><section><h2>Your requests</h2><div v-if="loading" class="empty">Loading requests…</div><div v-else class="requests"><article v-for="request in requests" :key="request.id" class="request"><div class="request-head"><div><h3>{{request.location_name}}</h3><p>{{request.address}}, {{request.suburb}}</p></div><span :class="request.status">{{request.status}}</span></div><p>{{request.description}}</p><small>Submitted {{date(request.created_at)}}<template v-if="request.preferred_date"> · Preferred: {{date(request.preferred_date)}}</template></small></article><p v-if="!requests.length" class="empty">You have not submitted any cleanup requests yet.</p></div></section></div></section></template>
<script setup>import{onMounted,reactive,ref}from'vue';import api from'../../api.js';const requests=ref([]),message=ref(''),error=ref(false),saving=ref(false),loading=ref(true),today=new Date().toISOString().slice(0,10);const blank=()=>({location_name:'',address:'',suburb:'',description:'',preferred_date:''});const form=reactive(blank());const date=v=>new Date(v).toLocaleDateString('en-ZA',{day:'numeric',month:'short',year:'numeric'});async function load(){loading.value=true;try{requests.value=(await api.get('/resident/cleanup-requests')).data}catch(e){error.value=true;message.value=e.response?.data?.message||'Unable to load your requests.'}finally{loading.value=false}}async function submit(){saving.value=true;message.value='';try{const{data}=await api.post('/resident/cleanup-requests',form);message.value=data.message;error.value=false;Object.assign(form,blank());load()}catch(e){error.value=true;message.value=e.response?.data?.message||'Unable to send your request.'}finally{saving.value=false}}onMounted(load)</script>
<style scoped>.page{width:min(1120px,100%);margin:auto;padding:3rem 1.5rem 4rem}header{max-width:700px;margin-bottom:1.5rem}.eyebrow{color:var(--green);font-size:.75rem;font-weight:800;text-transform:uppercase;letter-spacing:.1em;margin:0}h1,h2,h3{color:var(--green-dark)}h1{margin:.2rem 0}header p:not(.eyebrow){margin:0;color:var(--text-muted)}.layout{display:grid;grid-template-columns:370px 1fr;gap:1.5rem}.card,.request{background:#fff;border:1px solid var(--border);border-radius:12px;padding:1.25rem}.card h2{margin:0}label{display:grid;gap:.35rem;margin:.8rem 0;font-weight:700;font-size:.86rem;color:var(--green-dark)}label small{font-weight:400;color:var(--text-muted)}input,textarea{padding:.7rem;border:1px solid var(--border);border-radius:7px;resize:vertical}button{width:100%;border:0;border-radius:7px;padding:.75rem;cursor:pointer;background:var(--green);font-weight:800;color:var(--green-deeper)}button:disabled{opacity:.65}.requests{display:grid;gap:.8rem}.request-head{display:flex;justify-content:space-between;gap:.5rem}.request h3{margin:0}.request p{margin:.25rem 0;color:var(--text-muted)}.request small{color:var(--text-muted)}.request span{height:max-content;padding:.25rem .5rem;border-radius:99px;font-size:.75rem;font-weight:800;text-transform:capitalize}.new{background:#e6edf2;color:#395463}.reviewing{background:#fff1cb;color:#7a5300}.scheduled{background:#e6eefb;color:#294f88}.completed{background:#e6f5e8;color:#286033}.message{padding:.7rem;border-radius:7px}.success{background:#e7f5e8;color:#286033}.error{background:#fff0f0;color:#9b2525}.empty{color:var(--text-muted)}@media(max-width:760px){.layout{grid-template-columns:1fr}}</style>
